internal sealed partial class UnattendedTestRunner
{
    private sealed record TaskExtensionDelegate(string Location, string Signature, string ModuleMvid,
        int MetadataToken, string TargetType, int TargetIdentity, IReadOnlyList<string> TargetFields);
    private sealed record TaskExtensionObject(string Location, string RuntimeType,
        IReadOnlyList<string> Fields, IReadOnlyList<TaskExtensionDelegate> Callbacks);
    private sealed record TaskExtensionInventory(IReadOnlyList<TaskExtensionObject> Registrations,
        IReadOnlyList<TaskExtensionDelegate> LifecycleCallbacks, IReadOnlyList<string> ModelAttachedStates,
        int LifecycleObservers, int CloneListeners, int DefaultModifiers, int SavedSlots,
        int ExistingCapabilityOwners, int CapabilityCount, int ExistingBagOwners,
        bool SavedRegistrationFinalized, bool IsWholeOrderCertificate);

    private static readonly BindingFlags TaskAllInstanceFields = BindingFlags.Instance
        | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly;

    private static IEnumerable<FieldInfo> TaskInstanceFields(Type type)
    {
        for (Type? cursor = type; cursor != null; cursor = cursor.BaseType)
            foreach (FieldInfo field in cursor.GetFields(TaskAllInstanceFields)) yield return field;
    }

    private static string TaskFieldValue(object? value) => value switch
    {
        null => "null",
        Type type => "type:" + type.AssemblyQualifiedName,
        string text => "string:" + text,
        bool or byte or sbyte or short or ushort or int or uint or long or ulong or nint or nuint or float or double or decimal
            => "primitive:" + value,
        Enum => "enum:" + value.GetType().FullName + ":" + value,
        _ when value.GetType().IsValueType => "value:" + value.GetType().FullName + ":"
            + string.Join("|", TaskInstanceFields(value.GetType()).Select(field => field.Name + "="
                + TaskNonRecursiveValue(field.GetValue(value)))),
        _ => "opaque:" + value.GetType().FullName + ":" + RuntimeHelpers.GetHashCode(value)
    };

    private static string TaskNonRecursiveValue(object? value) => value switch
    {
        null => "null",
        Type type => "type:" + type.AssemblyQualifiedName,
        string text => "string:" + text,
        bool or byte or sbyte or short or ushort or int or uint or long or ulong or nint or nuint or float or double or decimal
            => "primitive:" + value,
        Enum => "enum:" + value.GetType().FullName + ":" + value,
        _ when value.GetType().IsValueType => "unreviewed-nested-value:" + value.GetType().FullName,
        _ => "opaque:" + value.GetType().FullName + ":" + RuntimeHelpers.GetHashCode(value)
    };

    private static string[] TaskObjectFields(object value) => TaskInstanceFields(value.GetType())
        .Select(field => field.DeclaringType!.FullName + "." + field.Name + "=" + TaskFieldValue(field.GetValue(value)))
        .OrderBy(text => text, StringComparer.Ordinal).ToArray();

    private static TaskExtensionDelegate TaskDescribeDelegate(string location, Delegate callback)
        => new(location, callback.Method.ToString()!, callback.Method.Module.ModuleVersionId.ToString(),
            callback.Method.MetadataToken, callback.Target?.GetType().AssemblyQualifiedName ?? "static",
            callback.Target is null ? 0 : RuntimeHelpers.GetHashCode(callback.Target),
            callback.Target is null ? [] : Array.AsReadOnly(TaskObjectFields(callback.Target)));

    private static TaskExtensionObject TaskDescribeRegistration(string location, object value)
    {
        List<TaskExtensionDelegate> callbacks = [];
        foreach (FieldInfo field in TaskInstanceFields(value.GetType()))
            if (field.GetValue(value) is Delegate callback)
                foreach (Delegate item in callback.GetInvocationList())
                    callbacks.Add(TaskDescribeDelegate(location + "/" + field.Name, item));
        return new(location, value.GetType().AssemblyQualifiedName!,
            Array.AsReadOnly(TaskObjectFields(value)), Array.AsReadOnly(callbacks.ToArray()));
    }

    private static object TaskStaticField(Type type, string name) => type.GetField(name,
        BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;

    private static T TaskUnderRegistryLock<T>(Type type, Func<T> reader)
    {
        var gate = (System.Threading.Lock)TaskStaticField(type, "SyncRoot");
        using (gate.EnterScope()) return reader();
    }

    private static TaskExtensionInventory TaskCaptureExtensionInventory(CombatState live)
    {
        Assembly runtime = typeof(ModelCapabilities).Assembly;
        Type cloneType = typeof(ModelCloneRegistry);
        Type defaultsType = runtime.GetType("STS2RitsuLib.Models.Capabilities.ModelCapabilityDefaults", true)!;
        Type savedType = runtime.GetType("STS2RitsuLib.Models.Capabilities.ModelSavedDataRegistry", true)!;
        Type savedRuntimeType = runtime.GetType("STS2RitsuLib.Models.Capabilities.ModelSavedDataRuntime", true)!;
        List<TaskExtensionObject> registrations = [];
        List<TaskExtensionDelegate> lifecycle = [];
        object[] cloneEntries = TaskUnderRegistryLock(cloneType,
            () => ((IDictionary)TaskStaticField(cloneType, "Listeners")).Values.Cast<object>().ToArray());
        object[] defaults = TaskUnderRegistryLock(defaultsType,
            () => ((IEnumerable)TaskStaticField(defaultsType, "Modifiers")).Cast<object>().ToArray());
        object[] slots = TaskUnderRegistryLock(savedType,
            () => ((IDictionary)TaskStaticField(savedType, "Slots")).Values.Cast<object>().ToArray());
        bool finalized = TaskUnderRegistryLock(savedType,
            () => (bool)TaskStaticField(savedType, "_registrationFinalized"));
        for (int i = 0; i < cloneEntries.Length; i++) registrations.Add(TaskDescribeRegistration("clone/" + i, cloneEntries[i]));
        for (int i = 0; i < defaults.Length; i++) registrations.Add(TaskDescribeRegistration("default/" + i, defaults[i]));
        for (int i = 0; i < slots.Length; i++) registrations.Add(TaskDescribeRegistration("saved-slot/" + i, slots[i]));
        Type framework = typeof(RitsuLibFramework);
        object[] observers = TaskUnderRegistryLock(framework,
            () => ((IEnumerable)TaskStaticField(framework, "_lifecycleObservers")).Cast<object>().ToArray());
        for (int i = 0; i < observers.Length; i++) registrations.Add(TaskDescribeRegistration("lifecycle-observer/" + i, observers[i]));
        // Each topic publishes an atomic snapshot. ReadSnapshot does not add an event topic.
        foreach (KeyValuePair<Type, object> entry in ((ConcurrentDictionary<Type, object>)TaskStaticField(framework, "LifecycleTopics"))
            .ToArray().OrderBy(entry => entry.Key.AssemblyQualifiedName, StringComparer.Ordinal))
        {
            Type eventType = entry.Key;
            var handlers = (IEnumerable)entry.Value!.GetType().GetMethod("ReadSnapshot")!.Invoke(entry.Value, null)!;
            int order = 0;
            foreach (Delegate handler in handlers)
                foreach (Delegate callback in handler.GetInvocationList())
                    lifecycle.Add(TaskDescribeDelegate("lifecycle/" + eventType.FullName + "/" + order++, callback));
        }
        var models = new HashSet<AbstractModel>(ReferenceEqualityComparer.Instance);
        foreach (AbstractModel model in live.IterateHookListeners()) models.Add(model);
        foreach (AbstractModel model in live.RunState.IterateHookListeners(live)) models.Add(model);
        foreach (Player owner in live.Players)
        foreach (CardModel card in owner.Deck.Cards.Concat(owner.PlayerCombatState!.AllCards))
        {
            models.Add(card);
            if (card.Enchantment is { } enchantment) models.Add(enchantment);
            if (card.Affliction is { } affliction) models.Add(affliction);
        }
        object bags = TaskStaticField(savedRuntimeType, "ModelBags");
        MethodInfo rawTryGet = bags.GetType().GetMethod("TryGetValue")!;
        List<string> attached = [];
        int capabilityOwners = 0, capabilityCount = 0, bagOwners = 0;
        foreach (AbstractModel model in models.OrderBy(model => model.GetType().FullName, StringComparer.Ordinal)
            .ThenBy(model => RuntimeHelpers.GetHashCode(model)))
        {
            string location = model.GetType().FullName + ":" + RuntimeHelpers.GetHashCode(model);
            if (ModelCapabilities.TryGet(model, out ModelCapabilitySet? capabilities))
            {
                capabilityOwners++;
                capabilityCount += capabilities.Count;
                attached.Add(location + "/capabilities=" + capabilities.Count);
            }
            // The reviewed Shared.dll AttachedState.TryGetValue only reads ConditionalWeakTable.
            // ModelSavedDataRuntime.TryGetBag additionally invokes import callbacks; do not use it.
            object?[] arguments = [model, null];
            if ((bool)rawTryGet.Invoke(bags, arguments)!)
            {
                bagOwners++;
                attached.Add(location + "/bag=" + string.Join("|", TaskObjectFields(arguments[1]!)));
            }
        }
        return new(Array.AsReadOnly(registrations.ToArray()), Array.AsReadOnly(lifecycle.ToArray()),
            Array.AsReadOnly(attached.ToArray()), observers.Length, cloneEntries.Length, defaults.Length,
            slots.Length, capabilityOwners, capabilityCount, bagOwners, finalized, false);
    }

    private async Task RunTaskExhaustExtensionRegistryAsync(CombatState live, Player player)
    {
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(player, sim,
            ((SimulatedCombatState)sim.State.CombatState).GetPlayerTurnNumber(player), root.Forecast,
            root.StartTurnNumber).StateText + "\nHISTORY=" + CardContinuationContractHistoryText(sim);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText, parentBefore = State(parent);
        Stopwatch captureTimer = Stopwatch.StartNew();
        TaskExtensionInventory initial = TaskCaptureExtensionInventory(live);
        captureTimer.Stop();
        string frozen = JsonSerializer.Serialize(initial);
        var children = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        await Task.WhenAll(children.Select(child => Task.Run(() => {
            using IDisposable scope = SimulationNotificationIsolation.Enter();
            if (State(child) != parentBefore || JsonSerializer.Serialize(initial) != frozen)
                throw new InvalidOperationException("Extension inventory/Fork changed.");
        })));
        // Registration snapshots invalidate a prospective certificate; they do not certify initial semantics.
        TaskExtensionInventory withLifecycle;
        using (RitsuLibFramework.SubscribeLifecycle<CardExhaustedEvent>(_ => { }, replayCurrentState: false))
        {
            withLifecycle = TaskCaptureExtensionInventory(live);
            if (JsonSerializer.Serialize(withLifecycle) == frozen
                || withLifecycle.LifecycleCallbacks.Count != initial.LifecycleCallbacks.Count + 1)
                throw new InvalidOperationException("Unknown lifecycle registration did not invalidate the stamp.");
        }
        var registry = ModelCloneRegistry.For("combat_solver_exhaust_extension_fixture");
        int nativeCloneCallbacks = 0;
        TaskExtensionInventory withClone;
        registry.Register("unknown-clone", _ => nativeCloneCallbacks++);
        try
        {
            withClone = TaskCaptureExtensionInventory(live);
            if (JsonSerializer.Serialize(withClone) == frozen || withClone.CloneListeners != initial.CloneListeners + 1)
                throw new InvalidOperationException("Unknown clone registration did not invalidate the stamp.");
            _ = player.PlayerCombatState!.Hand.Cards[0].MutableClone();
            if (nativeCloneCallbacks != 1)
                throw new InvalidOperationException("Native clone did not invoke its registered listener exactly once.");
        }
        finally { registry.Unregister("unknown-clone"); }
        TaskExtensionInventory after = TaskCaptureExtensionInventory(live);
        bool registrationMatches = JsonSerializer.Serialize(after) == frozen;
        bool frozenMatches = JsonSerializer.Serialize(initial) == frozen;
        bool parentMatches = State(parent) == parentBefore;
        bool liveMatches = ContinuationStamp.CaptureLive(live).StateText == liveBefore;
        _completedChecks.Add("TASK_EXHAUST_EXTENSIONS " + JsonSerializer.Serialize(new { initial,
            withLifecycle, withClone, after, nativeCloneCallbacks, forkCount = children.Length,
            captureMilliseconds = captureTimer.Elapsed.TotalMilliseconds,
            registrationMatches, frozenMatches, parentMatches, liveMatches,
            actualPrunes = 0, isWholeOrderCertificate = false }));
        if (!registrationMatches || !frozenMatches || !parentMatches || !liveMatches)
            throw new InvalidOperationException($"Registry cleanup/isolation differs: registrations={registrationMatches}, frozen={frozenMatches}, parent={parentMatches}, live={liveMatches}.");
        _completedChecks.Add("ExhaustExtensionRegistry:RealSilentBoss:TypedLifecycleObservers:ClonePredicatesListeners:DefaultModifiers:SavedSlots:RawAttachedBag:UnknownRegistrationInvalidation:NativeCloneCallback:16InitialForks:FrozenParentLiveIsolation");
    }
}

